-- Producción DIRITPTIM: dinero, celulares, migraciones, chips, ubicados y expulsados.
begin;
alter table public.intervenciones drop constraint if exists resultados_previstos_validos;
alter table public.intervenciones add constraint resultados_previstos_validos check (
 resultados_previstos <@ array['detenidos','requisitoriados','menores','victimas','prostitucion','dinero','celulares','migraciones','chips','expulsados','bienes','bandas','organizaciones','armas','drogas','vehiculos','personas_ubicadas','otros']::text[]
 and array_position(resultados_previstos,null) is null
);
create table if not exists public.intervencion_complementarios (
 id uuid primary key default gen_random_uuid(),
 intervencion_id uuid not null references public.intervenciones(id) on delete restrict,
 tipo text not null check(tipo in ('dinero','celulares','migraciones','chips','personas_ubicadas','expulsados')),
 datos jsonb not null check(jsonb_typeof(datos)='object'),
 version integer not null default 1 check(version>0),
 creado_por uuid not null default auth.uid() references public.perfiles(id),
 creado_en timestamptz not null default now(),
 actualizado_en timestamptz not null default now()
);
create index if not exists complementarios_operativo_idx on public.intervencion_complementarios(intervencion_id,creado_en,id);
alter table public.intervencion_complementarios enable row level security;
drop policy if exists complementarios_lectura on public.intervencion_complementarios;
-- Comprobar el ámbito explícitamente además de la RLS del operativo padre.
create policy complementarios_lectura on public.intervencion_complementarios for select to authenticated
using(public.usuario_activo() and exists(
 select 1 from public.intervenciones i
 where i.id=intervencion_complementarios.intervencion_id
 and public.puede_acceder_unidad(i.unidad)
));
drop policy if exists complementarios_alta on public.intervencion_complementarios;
create policy complementarios_alta on public.intervencion_complementarios for insert to authenticated with check(creado_por=auth.uid() and public.usuario_activo() and exists(select 1 from public.intervenciones i where i.id=intervencion_id and (public.es_administrador() or (i.creado_por=auth.uid() and i.unidad=public.unidad_actual()))));
drop policy if exists complementarios_edicion on public.intervencion_complementarios;
create policy complementarios_edicion on public.intervencion_complementarios for update to authenticated using(public.usuario_activo() and exists(select 1 from public.intervenciones i where i.id=intervencion_id and (public.es_administrador() or (i.creado_por=auth.uid() and i.unidad=public.unidad_actual())))) with check(public.usuario_activo() and exists(select 1 from public.intervenciones i where i.id=intervencion_id and (public.es_administrador() or (i.creado_por=auth.uid() and i.unidad=public.unidad_actual()))));
revoke all on public.intervencion_complementarios from public,anon,authenticated;
grant select,insert,update on public.intervencion_complementarios to authenticated;

create or replace function public.proteger_complementarios_operativo() returns trigger language plpgsql security invoker set search_path='' as $$
declare i public.intervenciones%rowtype; spec jsonb; field jsonb; k text; v jsonb; n numeric;
begin
 select * into i from public.intervenciones where id=new.intervencion_id for update;
 if not found or i.tipo not in ('operativo','megaoperativo') or not public.usuario_activo() or not(public.es_administrador() or (i.creado_por=auth.uid() and i.unidad=public.unidad_actual())) then raise exception 'No puede modificar registros de resultados complementarios de este operativo.' using errcode='42501'; end if;
 if tg_op='UPDATE' then
  if new.id is distinct from old.id or new.intervencion_id is distinct from old.intervencion_id or new.tipo is distinct from old.tipo or new.creado_por is distinct from old.creado_por or new.creado_en is distinct from old.creado_en then raise exception 'No se puede trasladar ni cambiar la identidad o categoría de este registro.' using errcode='42501'; end if;
  new.version:=old.version+1;
 else new.version:=1;new.creado_por:=auth.uid();new.creado_en:=now(); end if;
