A","PANAMA","PAPUA NUEVA GUINEA","PARAGUAY","PERU","PITCAIRN, ISLA","POLINESIA FRANCESA","POLONIA","PORTUGAL","PUERTO RICO","QATAR","REINA MAUD, TIERRA DE LA","REINO UNIDO","REPUBLICA CENTROAFRICANA","REPUBLICA CHECA","REPUBLICA DE MOLDAVIA","REPUBLICA DEMOCRATICA DEL CONGO","REPUBLICA DOMINICANA","REPUBLICA SUDAFRICANA","REUNION","RUANDA","RUMANIA","SAHARA OCCIDENTAL","SAINT-CHISTOPHER Y NIEVES","SALOMON, ISLAS","SALVADOR, EL","SAMOA","SAMOA NORTEAMERICANA","SAN MARINO","SAN PEDRO Y MIQUELON","SAN VICENTE Y LAS GRANADINAS","SANTA ELENA","SANTA LUCIA","SANTO TOME Y PRINCIPE","SENEGAL","SERBIA","SEYCHELLES","SIERRA LEONA","SIKKIM","SINGAPUR","SIRIA","SOMALIA","SRILANKA","SUDAN","SUECIA","SUIZA","SURINAM","SVALBARD Y JAN MAYEN, ISLA","SWAZILANDIA","TADJIKISTAN","TAILANDIA","TAIWAN","TANZANIA","TIMOR","TOGO","TOKELAU","TONGA","TRINIDAD Y TOBAGO","TUNEZ","TURKMENISTAN","TURKS Y CAICOS, ISLAS","TURQUIA","TUVALU","UCRANIA","UGANDA","UNITED STATES MINOR OUTLING ISLANDS","URUGUAY","UZBEKISTAN","VANUATU","VATICANO","VENEZUELA","VIETNAM","VIRGENES, ISLAS (ESTADOS UNIDOS)","VIRGENES, ISLAS (REINO UNIDO)","WAKE, ISLA DE","WALLIS Y FUTUNA, ISLAS","YEMEN","ZAMBIA","ZIMBABWE"]},{"key":"tipo_documento","label":"Tipo de documento","type":"text","group":"registro","required":false,"options":["DNI","CARNET DE EXTRANJERIA","CEDULA DE IDENTIDAD","SDPV","SALVO CONDUCTO","LAISER PASSER","PTP(PERMISO TEMPORAL PERMANENCIA)","PASAPORTE"]},{"key":"numero_documento","label":"Número de documento","type":"text","group":"registro","required":false},{"key":"condicion","label":"Condición","type":"text","group":"registro","required":true},{"key":"ley_migraciones","label":"Ley de Migraciones","type":"text","group":"registro","required":true},{"key":"subtipo_infraccion","label":"Subtipo de infracción","type":"text","group":"registro","required":true}]}$schema$::jsonb -> new.tipo;
 if spec is null then raise exception 'Categoría inválida.' using errcode='22023';end if;
 for k,v in select * from jsonb_each(new.datos) loop
  select value into field from jsonb_array_elements(spec) where value->>'key'=k;
  if field is null or jsonb_typeof(v) not in ('string','number','null') or length(new.datos->>k)>2000 then raise exception 'Campo inválido: %',k using errcode='22023';end if;
  if v='null'::jsonb then continue;end if;
  if field->>'type'='number' then
   if jsonb_typeof(v)<>'number' then raise exception 'Se esperaba número en %',k using errcode='22023';end if;
   n:=(new.datos->>k)::numeric;
   if n<(field->>'min')::numeric or n>(field->>'max')::numeric or mod(n,(field->>'step')::numeric)<>0 then raise exception 'Número fuera de rango en %',k using errcode='22023';end if;
  else
   if jsonb_typeof(v)<>'string' then raise exception 'Se esperaba texto en %',k using errcode='22023';end if;
   if field->>'type'='date' then
    if (v#>>'{}') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Fecha inválida.' using errcode='22023';end if;
    perform (v#>>'{}')::date;
   end if;
   if field->>'type'='time' and (v#>>'{}') !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$' then raise exception 'Hora inválida.' using errcode='22023';end if;
  end if;
  if field ? 'options' and not (field->'options' @> jsonb_build_array(v)) then raise exception 'Opción inválida en %',k using errcode='22023';end if;
 end loop;
 for field in select * from jsonb_array_elements(spec) loop
  if (field->>'required')::boolean and nullif(btrim(new.datos->>(field->>'key')),'') is null then raise exception 'Complete %',field->>'label' using errcode='22023';end if;
 end loop;
 if new.tipo='dinero' and coalesce((new.datos->>'soles')::numeric,0)<=0 and coalesce((new.datos->>'dolares')::numeric,0)<=0 and coalesce((new.datos->>'euros')::numeric,0)<=0 and nullif(btrim(new.datos->>'dinero_otro'),'') is null then raise exception 'Indique al menos un importe o la otra moneda.' using errcode='22023';end if;
 if nullif(btrim(new.datos->>'numero_documento'),'') is not null and nullif(btrim(new.datos->>'tipo_documento'),'') is null then raise exception 'Seleccione el tipo de documento.' using errcode='22023';end if;
 if new.tipo='personas_ubicadas' and (new.datos->>'condicion_edad') is distinct from (case when (new.datos->>'edad')::numeric<18 then 'MENOR' else 'MAYOR' end) then raise exception 'La condición de edad no coincide con la edad.' using errcode='22023';end if;
 if new.tipo='celulares' and coalesce((new.datos->>'cantidad')::numeric,0)<>1 and (nullif(btrim(new.datos->>'imei_fisico'),'') is not null or nullif(btrim(new.datos->>'imei_logico'),'') is not null) then raise exception 'Registre un solo equipo cuando indique IMEI.' using errcode='22023';end if;
 new.actualizado_en:=now();
 update public.intervenciones set resultados_previstos=case when new.tipo=any(resultados_previstos) then resultados_previstos else array_append(resultados_previstos,new.tipo) end where id=i.id;
 return new;
end $$;
drop trigger if exists proteger_complementarios_operativo on public.intervencion_complementarios;
create trigger proteger_complementarios_operativo before insert or update on public.intervencion_complementarios for each row execute function public.proteger_complementarios_operativo();
create or replace function public.conservar_complementarios_registrados() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if exists(select 1 from public.intervencion_complementarios r where r.intervencion_id=old.id and (new.tipo='directa' or not(r.tipo=any(new.resultados_previstos)))) then raise exception 'El operativo ya tiene registros de resultados complementarios.' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists conservar_complementarios_registrados on public.intervenciones;
create trigger conservar_complementarios_registrados before update of tipo,resultados_previstos on public.intervenciones for each row execute function public.conservar_complementarios_registrados();
create or replace function public.guardar_complementarios_operativo(p_id uuid,p_intervencion uuid,p_version integer,p_tipo text,p_datos jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare i public.intervenciones%rowtype; m public.intervencion_complementarios%rowtype;
begin
 if p_id is null or p_intervencion is null or p_version is null or p_version<0 or not public.usuario_activo() then raise exception 'Solicitud inválida.' using errcode='22023';end if;
 select * into i from public.intervenciones where id=p_intervencion for update;
 if not found or not(public.es_administrador() or (i.creado_por=auth.uid() and i.unidad=public.unidad_actual())) then raise exception 'Operativo no disponible para edición.' using errcode='42501';end if;
 select * into m from public.intervencion_complementarios where id=p_id for update;
 if found then
  if m.intervencion_id<>p_intervencion or m.tipo<>p_tipo then raise exception 'El registro pertenece a otro operativo o categoría.' using errcode='42501';end if;
  if m.version=p_version+1 and m.datos=p_datos then return jsonb_build_object('id',m.id,'version',m.version,'operativo_version',i.version);end if;
  if m.version<>p_version then raise exception 'El registro cambió. Actualice antes de editar.' using errcode='40001';end if;
  update public.intervencion_complementarios set datos=p_datos where id=p_id returning * into m;
 else
  if p_version<>0 then raise exception 'Registro no disponible.' using errcode='40001';end if;
  insert into public.intervencion_complementarios(id,intervencion_id,tipo,datos) values(p_id,p_intervencion,p_tipo,p_datos) returning * into m;
 end if;
 return jsonb_build_object('id',m.id,'version',m.version,'operativo_version',(select version from public.intervenciones where id=i.id));
end $$;
revoke all on function public.proteger_complementarios_operativo(),public.conservar_complementarios_registrados(),public.guardar_complementarios_operativo(uuid,uuid,integer,text,jsonb) from public;
grant execute on function public.guardar_complementarios_operativo(uuid,uuid,integer,text,jsonb) to authenticated;
notify pgrst, 'reload schema';
commit;
